using System;using System.Drawing;using System.Windows.Forms;
namespace LoopFive {
 public class FxPage:UserControl {
  Engine engine;ComboBox section,bank,slot;Panel scroll;bool refreshing,rebuildQueued;
  public FxPage(Engine e){engine=e;Dock=DockStyle.Fill;Theme.Style(this);FlowLayoutPanel top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48,Padding=new Padding(10)};section=Theme.Combo(new string[]{"INPUT FX · entrada","TRACK FX · reproducción"});bank=Theme.Combo(new string[]{"Banco A","Banco B","Banco C","Banco D"});bank.Width=110;slot=Theme.Combo(new string[]{"FX A","FX B","FX C","FX D"});slot.Width=90;top.Controls.AddRange(new Control[]{section,bank,slot});Label summary=Theme.Label("49 familias propias + 4 efectos de reproducción");top.Controls.Add(summary);scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};Controls.Add(scroll);Controls.Add(top);section.SelectedIndexChanged+=Changed;bank.SelectedIndexChanged+=Changed;slot.SelectedIndexChanged+=Changed;Rebuild();}
  void QueueRebuild(){if(rebuildQueued||!IsHandleCreated)return;rebuildQueued=true;BeginInvoke((Action)delegate{rebuildQueued=false;if(!IsDisposed){Rebuild();Language.Apply(this);}});}
  void Changed(object sender,EventArgs e){if(!refreshing)Rebuild();}
  public void SelectSlot(bool input,int b,int s){refreshing=true;section.SelectedIndex=input?0:1;bank.SelectedIndex=b;slot.SelectedIndex=s;refreshing=false;Rebuild();}
  public void RefreshModel(){Rebuild();}
  void Change(Action action){lock(engine.Gate){action();engine.Dirty=true;}}
  void Rebuild(){if(scroll==null)return;while(scroll.Controls.Count>0)scroll.Controls[0].Dispose();bool input=section.SelectedIndex==0;ChainConfig chain=input?engine.Config.InputFx:engine.Config.TrackFx;FxConfig f=chain.Slots[bank.SelectedIndex*4+slot.SelectedIndex];EditorGrid grid=new EditorGrid();scroll.Controls.Add(grid);
   grid.Bool("Efecto activado",f.On,delegate(bool b){Change(delegate{if(b&&chain.Single)for(int i=0;i<4;i++)chain.Slots[bank.SelectedIndex*4+i].On=false;f.On=b;});});string[] types=input?FxCatalog.Input:FxCatalog.All;ComboBox type=grid.Choice("Tipo de procesamiento",types,Math.Max(0,Array.IndexOf(types,f.Type)),delegate(int i){Change(delegate{f.Type=types[i];f.Detailed=true;if(f.Detail==null)f.Detail=new FxDetail();});QueueRebuild();});Label description=Theme.Label(FxKnowledge.Description(f.Type));description.MaximumSize=new Size(790,0);grid.Row("Sobre este algoritmo",description);type.SelectedIndexChanged+=delegate{description.Text=FxKnowledge.Description(f.Type);};
   Language.Register("Controles detallados (modo nuevo)","Detailed controls (new mode)");grid.Bool("Controles detallados (modo nuevo)",f.Detailed,delegate(bool value){Change(delegate{f.Detailed=value;if(f.Detail==null)f.Detail=new FxDetail();});QueueRebuild();});
   if(!f.Detailed){   grid.Bool("Botón momentáneo",f.Momentary,delegate(bool b){Change(delegate{f.Momentary=b;});});grid.Number("Amount / profundidad (%)",f.Amount*100,0,100,delegate(float v){Change(delegate{f.Amount=v/100;});},0);grid.Number("Velocidad / tiempo (%)",f.Rate*100,0,100,delegate(float v){Change(delegate{f.Rate=v/100;});},0);grid.Number("Mezcla dry / wet (%)",f.Mix*100,0,100,delegate(float v){Change(delegate{f.Mix=v/100;});},0);grid.Number("Realimentación / resonancia (%)",f.Feedback*100,0,94,delegate(float v){Change(delegate{f.Feedback=v/100;});},0);grid.Bool("Velocidad sincronizada al tempo",f.Sync,delegate(bool b){Change(delegate{f.Sync=b;});});grid.Number("Duración sincronizada (pulsos)",f.Beats,.0625f,16,delegate(float v){Change(delegate{f.Beats=v;});},4);
   grid.Number("Transposición (semitonos)",f.Semitones,-36,48,delegate(float v){Change(delegate{f.Semitones=(int)v;});},0);grid.Number("Nota de oscilador (MIDI)",f.Note,12,120,delegate(float v){Change(delegate{f.Note=(int)v;});},0);grid.Choice("Variante del algoritmo",new string[]{"Modo 1","Modo 2"},f.Mode==2?1:0,delegate(int i){Change(delegate{f.Mode=i+1;});});
}
   else {
    grid.Bool("Botón momentáneo",f.Momentary,delegate(bool b){Change(delegate{f.Momentary=b;});});grid.Number("Mezcla dry / wet (%)",f.Mix*100,0,100,delegate(float v){Change(delegate{f.Mix=v/100;});},0);
    if(FxEditor.UsesAmount(f.Type))grid.Number("Amount / profundidad (%)",f.Amount*100,0,100,delegate(float v){Change(delegate{f.Amount=v/100;});},0);
    if(FxEditor.UsesFeedback(f.Type))grid.Number("Realimentación / resonancia (%)",f.Feedback*100,0,94,delegate(float v){Change(delegate{f.Feedback=v/100;});},0);
    if(FxEditor.UsesClock(f.Type)){grid.Bool("Velocidad sincronizada al tempo",f.Sync,delegate(bool b){Change(delegate{f.Sync=b;});});grid.Number("Duración sincronizada (pulsos)",f.Beats,.0625f,16,delegate(float v){Change(delegate{f.Beats=v;});},4);}
    if(FxEditor.IsPitch(f.Type))grid.Number("Transposición (semitonos)",f.Semitones,-36,48,delegate(float v){Change(delegate{f.Semitones=(int)v;});},0);
    if(f.Type=="OCTAVE")grid.Choice("Variante del algoritmo",new string[]{"-1 OCT","-2 OCT"},f.Mode==2?1:0,delegate(int i){Change(delegate{f.Mode=i+1;});});
   }
   if(f.Detailed)FxEditor.Build(grid,f,input,Change,QueueRebuild);
   Language.Register("Secuencia de nivel / Amount","Level / Amount sequence");grid.Bool(f.Detailed?"Secuencia de nivel / Amount":"Secuencia de Amount",f.Sequence,delegate(bool b){Change(delegate{f.Sequence=b;});});grid.Bool("Secuencia sincronizada",f.SequenceSync,delegate(bool b){Change(delegate{f.SequenceSync=b;});});grid.Bool("Reiniciar secuencia al activar",f.SequenceRetrigger,delegate(bool b){Change(delegate{f.SequenceRetrigger=b;});});grid.Number("Pasos activos",f.Steps,1,16,delegate(float v){Change(delegate{f.Steps=(int)v;});},0);StepEditor sequence=new StepEditor{Values=f.SequenceValues,Dock=DockStyle.Fill,Height=125};sequence.Edited+=delegate{engine.Dirty=true;};grid.Row("Valores por paso · arrastra",sequence);grid.Note("La secuencia modifica Amount en pasos de la duración sincronizada. Los controles tienen efecto según el algoritmo: semitonos para TRANSPOSE / PITCH BEND / HRM, nota MIDI para osciladores, modo 2 para TAPE ECHO / ROLL / OCTAVE. Los valores no son una copia de los parámetros internos de BOSS.");
   FlowLayoutPanel target=new FlowLayoutPanel{AutoSize=true};for(int i=0;i<(input?2:5);i++){int n=i;CheckBox c=Theme.Check(input?(i==0?"L":"R"):"Pista "+(i+1));c.Checked=(chain.Target&(1<<i))!=0;c.CheckedChanged+=delegate{Change(delegate{if(c.Checked)chain.Target|=1<<n;else chain.Target&=~(1<<n);});};target.Controls.Add(c);}grid.Row("Destino de toda la cadena",target);
   FlowLayoutPanel tools=new FlowLayoutPanel{AutoSize=true};Button bypass=Theme.Button("Apagar banco",delegate{Change(delegate{for(int i=0;i<4;i++)chain.Slots[bank.SelectedIndex*4+i].On=false;});Rebuild();});bypass.Width=140;tools.Controls.Add(bypass);ComboBox destination=Theme.Combo(new string[]{"A","B","C","D"});destination.Width=55;tools.Controls.Add(destination);Button copy=Theme.Button("Copiar banco a →",delegate{int source=bank.SelectedIndex,dest=destination.SelectedIndex;if(source==dest)return;Change(delegate{for(int i=0;i<4;i++)chain.Slots[dest*4+i]=Storage.Clone(chain.Slots[source*4+i]);});});copy.Width=150;tools.Controls.Add(copy);grid.Row("Bancos",tools);Language.Register("Guía comunitaria del efecto","Community effect guide");Button guide=Theme.Button("Guía comunitaria del efecto",delegate{System.Diagnostics.Process.Start(FxKnowledge.Source(f.Type));});guide.Width=300;grid.Row("Info",guide);Language.Apply(this);
  }
 }
 public class DrumGrid:Control {
  Engine engine;public DrumGrid(Engine e){engine=e;Dock=DockStyle.Top;Height=280;SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer,true);Cursor=Cursors.Hand;}
  protected override void OnPaint(PaintEventArgs e){Graphics g=e.Graphics;RhythmConfig c=engine.Config.Rhythm;byte[] pattern=c.Pattern==210?c.UserSteps:RhythmEngine.Pattern(c.Pattern,c.Variation);int start=135,w=Math.Max(1,(Width-start-10)/16);for(int n=0;n<8;n++){TextRenderer.DrawText(g,RhythmEngine.Instruments[n],Theme.Small,new Rectangle(10,29+n*29,122,27),Theme.Muted,TextFormatFlags.VerticalCenter);for(int i=0;i<16;i++){Rectangle r=new Rectangle(start+i*w+2,32+n*29,w-5,21);Color color=(pattern[i]&(1<<n))!=0?Theme.Green:Theme.Panel;if(c.Enabled&&i==engine.Drums.Step)color=(pattern[i]&(1<<n))!=0?Theme.Amber:Color.FromArgb(55,65,78);using(Brush b=new SolidBrush(color))g.FillRectangle(b,r);}}for(int i=0;i<16;i++)TextRenderer.DrawText(g,(i+1).ToString(),Theme.Small,new Rectangle(start+i*w,5,w,20),Theme.Muted,TextFormatFlags.HorizontalCenter);}
  protected override void OnMouseDown(MouseEventArgs e){int w=Math.Max(1,(Width-145)/16),n=(e.Y-32)/29,i=(e.X-135)/w;if(e.X<135||e.Y<32||n<0||n>7||i<0||i>15)return;lock(engine.Gate){if(engine.Config.Rhythm.Pattern!=210)return;engine.Config.Rhythm.UserSteps[i]^=(byte)(1<<n);engine.Dirty=true;}Invalidate();}
 }
 public class RhythmPage:UserControl {
  Engine engine;bool refreshing;CheckBox enabled;ComboBox pattern,kit,variation,startMode,stopMode;CheckBox intro;NumericUpDown volume,swing,numerator,denominator;DrumGrid grid;Label label;
  public RhythmPage(Engine e){engine=e;Dock=DockStyle.Fill;Theme.Style(this);AutoScroll=true;EditorGrid controls=new EditorGrid();Controls.Add(controls);enabled=controls.Bool("Reproducir ritmo",e.Config.Rhythm.Enabled,delegate(bool b){if(!refreshing)Change(delegate{e.Config.Rhythm.Enabled=b;});});string[] names=new string[211];for(int i=0;i<211;i++)names[i]=RhythmEngine.PatternName(i);pattern=controls.Choice("Patrón propio",names,e.Config.Rhythm.Pattern,delegate(int v){if(!refreshing)Change(delegate{e.Config.Rhythm.Pattern=v;});});kit=controls.Choice("Kit sintetizado",RhythmEngine.Kits,0,delegate(int v){if(!refreshing)Change(delegate{e.Config.Rhythm.Kit=v;});});variation=controls.Choice("Variación · siguiente compás",new string[]{"A","B","C","D"},0,delegate(int v){if(!refreshing)lock(e.Gate){if(e.Config.Rhythm.Enabled)e.Drums.PendingVariation=v;else e.Config.Rhythm.Variation=v;e.Dirty=true;}});
   volume=controls.Number("Volumen (%)",45,0,200,delegate(float v){if(!refreshing)Change(delegate{e.Config.Rhythm.Level=v/100;});},0);swing=controls.Number("Swing (%)",0,0,100,delegate(float v){if(!refreshing)Change(delegate{e.Config.Rhythm.Swing=v/100;});},0);numerator=controls.Number("Pulsos del compás",4,2,15,delegate(float v){if(!refreshing)Change(delegate{e.Config.Rhythm.BeatsPerBar=(int)v;});},0);denominator=controls.Number("Denominador (4 u 8)",4,4,8,delegate(float v){if(!refreshing)Change(delegate{e.Config.Rhythm.Denominator=v<6?4:8;});},0);denominator.Increment=4;
   startMode=controls.Choice("Inicio automático",new string[]{"Manual","Al grabar / reproducir pista","Al terminar la grabación"},e.Config.Rhythm.StartMode,delegate(int v){if(!refreshing)Change(delegate{e.Config.Rhythm.StartMode=v;});});stopMode=controls.Choice("Al detener todas las pistas",new string[]{"Mantener ritmo","Parada inmediata","Ending de un compás"},e.Config.Rhythm.StopMode,delegate(int v){if(!refreshing)Change(delegate{e.Config.Rhythm.StopMode=v;});});intro=controls.Bool("Intro en el primer compás",e.Config.Rhythm.Intro,delegate(bool b){if(!refreshing)Change(delegate{e.Config.Rhythm.Intro=b;});});
   FlowLayoutPanel actions=new FlowLayoutPanel{AutoSize=true};Add(actions,"FILL",delegate{Change(delegate{e.Config.Rhythm.Fill=true;});});Add(actions,"ENDING",delegate{Change(delegate{e.Config.Rhythm.Ending=true;});});Add(actions,"Copiar a USER",delegate{Change(delegate{e.Config.Rhythm.UserSteps=RhythmEngine.Pattern(e.Config.Rhythm.Pattern==210?0:e.Config.Rhythm.Pattern,e.Config.Rhythm.Variation);e.Config.Rhythm.Pattern=210;});RefreshModel();});Add(actions,"Importar MIDI…",delegate{using(OpenFileDialog d=new OpenFileDialog{Filter=Language.Filter("Patrón MIDI estándar|*.mid;*.midi")})if(d.ShowDialog()==DialogResult.OK){MidiPattern p=MidiPattern.Read(d.FileName);Change(delegate{e.Config.Rhythm.UserSteps=p.Steps;e.Config.Rhythm.Pattern=210;e.Config.Rhythm.BeatsPerBar=p.Numerator;e.Config.Rhythm.Denominator=p.Denominator;e.Config.Bpm=p.Bpm;});RefreshModel();}});controls.Row("Interpretación",actions);
   label=Theme.Label("Haz clic en las celdas de USER para editar. Las variaciones se aplican en el siguiente compás.");label.MaximumSize=new Size(700,0);controls.Row("Editor",label);grid=new DrumGrid(e);controls.Row("8 instrumentos / 16 pasos",grid);FlowLayoutPanel pads=new FlowLayoutPanel{AutoSize=true};for(int i=0;i<8;i++){int n=i;Add(pads,RhythmEngine.Instruments[i],delegate{lock(e.Gate)e.Drums.Hit(n,1);});}controls.Row("Pads",pads);controls.Note("210 patrones procedurales y 16 kits de síntesis propios. No contienen grabaciones ni patrones extraídos de BOSS. Cada compás se divide en 16 pasos, también en compases irregulares.");}
  void Add(FlowLayoutPanel p,string text,Action a){Button b=Theme.Button(text,a);b.Width=130;p.Controls.Add(b);}
  void Change(Action a){lock(engine.Gate){a();engine.Dirty=true;}}
  public void RefreshModel(){refreshing=true;RhythmConfig c=engine.Config.Rhythm;enabled.Checked=c.Enabled;pattern.SelectedIndex=c.Pattern;kit.SelectedIndex=c.Kit;variation.SelectedIndex=c.Variation;volume.Value=(decimal)(c.Level*100);swing.Value=(decimal)(c.Swing*100);numerator.Value=c.BeatsPerBar;denominator.Value=c.Denominator;startMode.SelectedIndex=c.StartMode;stopMode.SelectedIndex=c.StopMode;intro.Checked=c.Intro;refreshing=false;grid.Invalidate();}
  public void Tick(){refreshing=true;enabled.Checked=engine.Config.Rhythm.Enabled;refreshing=false;grid.Invalidate();}
 }
}
